9 `include "common_cells/assertions.svh"
10 
11 module spi_host
12   import spi_host_reg_pkg::*;
13 #(
14   parameter type reg_req_t = logic,
15   parameter type reg_rsp_t = logic
16 ) (
17   input              clk_i,
18   input              rst_ni,
19   input              clk_core_i,
20   input              rst_core_ni,
21 
22   // Register interface
23   input  reg_req_t reg_req_i,
24   output reg_rsp_t reg_rsp_o,
25 
26   // SPI Interface
27   output logic             cio_sck_o,
28   output logic             cio_sck_en_o,
29   output logic [NumCS-1:0] cio_csb_o,
30   output logic [NumCS-1:0] cio_csb_en_o,
31   output logic [3:0]       cio_sd_o,
32   output logic [3:0]       cio_sd_en_o,
33   input        [3:0]       cio_sd_i,
34 
35   output logic             intr_error_o,
36   output logic             intr_spi_event_o
37 );
38 
39   import spi_host_cmd_pkg::*;
40 
41   spi_host_reg2hw_t reg2hw;
42   spi_host_hw2reg_t hw2reg;
43 
44   reg_req_t fifo_win_h2d;
45   reg_rsp_t fifo_win_d2h;
46 
47   // Register module
48   spi_host_reg_top #(
49     .reg_req_t (reg_req_t),
50     .reg_rsp_t (reg_rsp_t)
51   ) u_reg (
52     .clk_i,
53     .rst_ni,
54     .reg_req_i,
55     .reg_rsp_o,
56     .reg_req_win_o (fifo_win_h2d),
57     .reg_rsp_win_i (fifo_win_d2h),
58     .reg2hw,
59     .hw2reg,
60     .devmode_i  (1'b1)
61   );
62 
63   logic             sck;
64   logic [NumCS-1:0] csb;
65   logic [3:0]       sd_out;
66   logic [3:0]       sd_en;
67   logic [3:0]       sd_i;
68 
69   assign cio_sck_o    = sck;
70   assign cio_sck_en_o = 1'b1;
71   assign cio_csb_o    = csb;
72   assign cio_csb_en_o = {NumCS{1'b1}};
73   assign cio_sd_o     = sd_out;
74   assign cio_sd_en_o  = sd_en;
75 
76   assign sd_i            = cio_sd_i;
77 
78   assign hw2reg.status.byteorder.d  = ByteOrder;
79   assign hw2reg.status.byteorder.de = 1'b1;
80 
81   logic command_valid;
82   logic core_command_valid;
83   logic command_busy;
84   logic core_command_ready;
85 
86   command_t core_command, command;
87   logic error_csid_inval;
88   logic error_cmd_inval;
89   logic error_busy;
90   logic test_csid_inval;
91   logic test_dir_inval;
92   logic test_speed_inval;
93 
94   assign test_csid_inval  = (reg2hw.csid.q >= NumCS);
95 
96   always_comb begin
97     test_speed_inval           = 1'b1;
98     test_dir_inval             = 1'b1;
99     unique case (reg2hw.command.speed.q)
100       Standard: begin
101         test_dir_inval   = 1'b0;
102         test_speed_inval = 1'b0;
103       end
104       Dual, Quad: begin
105         test_dir_inval   = (reg2hw.command.direction.q == Bidir);
106         test_speed_inval = 1'b0;
107       end
108       default: begin
109       end
110     endcase
111   end
112 
113   always_comb begin
114     command.segment.cmd_rd_en = 1'b0;
115     command.segment.cmd_wr_en = 1'b0;
116     unique case (reg2hw.command.direction.q)
117       RdOnly: begin
118         command.segment.cmd_rd_en = 1'b1;
119       end
120       WrOnly: begin
121         command.segment.cmd_wr_en = 1'b1;
122       end
123       Bidir: begin
124         command.segment.cmd_rd_en = 1'b1;
125         command.segment.cmd_wr_en = 1'b1;
126       end
127       default: begin
128       end
129     endcase
130   end
131 
132   assign error_csid_inval = command_valid & ~command_busy &
133                             test_csid_inval;
134   assign error_cmd_inval  = command_valid & ~command_busy &
135                             (test_speed_inval | test_dir_inval);
136 
137   spi_host_reg_pkg::spi_host_reg2hw_configopts_mreg_t configopts;
138 
139   if (NumCS == 1) begin : gen_single_device
140     assign configopts   = reg2hw.configopts[0];
141     assign command.csid = '0;
142   end else begin : gen_multiple_devices
143     logic [CSW-1:0] csid;
144     assign csid         = (test_csid_inval) ? '0 : reg2hw.csid.q[CSW-1:0];
145     assign configopts   = reg2hw.configopts[csid];
146     assign command.csid = csid;
147   end : gen_multiple_devices
148 
149   assign command.configopts.clkdiv   = configopts.clkdiv.q;
150   assign command.configopts.csnidle  = configopts.csnidle.q;
151   assign command.configopts.csnlead  = configopts.csnlead.q;
152   assign command.configopts.csntrail = configopts.csntrail.q;
153   assign command.configopts.full_cyc = configopts.fullcyc.q;
154   assign command.configopts.cpha     = configopts.cpha.q;
155   assign command.configopts.cpol     = configopts.cpol.q;
156 
157   assign command.segment.len         = reg2hw.command.len.q;
158   assign command.segment.csaat       = reg2hw.command.csaat.q;
159   assign command.segment.speed       = reg2hw.command.speed.q;
160 
161 
162   logic [3:0] cmd_qes;
163 
164   assign cmd_qes = {
165       reg2hw.command.len.qe,
166       reg2hw.command.speed.qe,
167       reg2hw.command.direction.qe,
168       reg2hw.command.csaat.qe
169   };
170 
171   // Any qe pin from COMMAND will suffice.
172   assign command_valid = |cmd_qes;
173 
174   // TODO: Determine the correct way to trigger a command.
175   // The following assertion confirms that at lease in
176   // some cases, the writes to COMMAND are not atomic.
177   //
178   // Disabling this assertion for now
179   //`ASSERT(CmdAtomicity_A, &cmd_qes ^ |cmd_qes, clk_i, rst_ni);
180 
181   logic active, core_active;
182   logic rx_stall, core_rx_stall;
183   logic tx_stall, core_tx_stall;
184 
185   assign hw2reg.status.ready.d    = ~command_busy;
186   assign hw2reg.status.active.d   = active;
187   assign hw2reg.status.rxstall.d  = rx_stall;
188   assign hw2reg.status.txstall.d  = tx_stall;
189 
190   assign hw2reg.status.ready.de   = 1'b1;
191   assign hw2reg.status.active.de  = 1'b1;
192   assign hw2reg.status.rxstall.de = 1'b1;
193   assign hw2reg.status.txstall.de = 1'b1;
194 
195   logic sw_rst, core_sw_rst;
196 
197   spi_host_command_cdc u_cmd_cdc (
198     .clk_i,
199     .rst_ni,
200     .clk_core_i,
201     .rst_core_ni,
202     .command_i            (command),
203     .command_valid_i      (command_valid),
204     .command_busy_o       (command_busy),
205     .core_command_o       (core_command),
206     .core_command_valid_o (core_command_valid),
207     .core_command_ready_i (core_command_ready),
208     .error_busy_o         (error_busy),
209 
210     .sw_rst_i             (sw_rst),
211     .core_sw_rst_i        (core_sw_rst)
212   );
213 
214   logic [31:0] tx_data;
215   logic [3:0]  tx_be;
216   logic        tx_valid;
217   logic        tx_ready;
218 
219   logic [31:0] rx_data;
220   logic        rx_valid;
221   logic        rx_ready;
222 
223   spi_host_window #(
224     .reg_req_t  (reg_req_t),
225     .reg_rsp_t  (reg_rsp_t)
226   ) u_window (
227     .clk_i,
228     .rst_ni,
229     .win_i      (fifo_win_h2d),
230     .win_o      (fifo_win_d2h),
231     .tx_data_o  (tx_data),
232     .tx_be_o    (tx_be),
233     .tx_valid_o (tx_valid),
234     .rx_data_i  (rx_data),
235     .rx_ready_o (rx_ready)
236   );
237 
238   logic [31:0] core_tx_data;
239   logic [3:0]  core_tx_be;
240   logic        core_tx_valid;
241   logic        core_tx_ready;
242 
243   logic [31:0] core_rx_data;
244   logic        core_rx_valid;
245   logic        core_rx_ready;
246 
247   logic [7:0]  rx_watermark;
248   logic [7:0]  tx_watermark;
249   logic [7:0]  rx_qd;
250   logic [7:0]  tx_qd;
251 
252   logic        tx_empty, tx_full, tx_wm;
253   logic        rx_empty, rx_full, rx_wm;
254 
255   assign rx_watermark = reg2hw.control.rx_watermark.q;
256   assign tx_watermark = reg2hw.control.tx_watermark.q;
257 
258   assign hw2reg.status.txqd.d    = tx_qd;
259   assign hw2reg.status.rxqd.d    = rx_qd;
260   assign hw2reg.status.txwm.d    = tx_wm;
261   assign hw2reg.status.rxwm.d    = rx_wm;
262   assign hw2reg.status.rxempty.d = rx_empty;
263   assign hw2reg.status.txempty.d = tx_empty;
264   assign hw2reg.status.rxfull.d  = rx_full;
265   assign hw2reg.status.txfull.d  = tx_full;
266 
267   assign hw2reg.status.txqd.de    = 1'b1;
268   assign hw2reg.status.rxqd.de    = 1'b1;
269   assign hw2reg.status.txwm.de    = 1'b1;
270   assign hw2reg.status.rxwm.de    = 1'b1;
271   assign hw2reg.status.rxempty.de = 1'b1;
272   assign hw2reg.status.txempty.de = 1'b1;
273   assign hw2reg.status.rxfull.de  = 1'b1;
274   assign hw2reg.status.txfull.de  = 1'b1;
275 
276   logic error_overflow, error_underflow;
277 
278   // Since the CDC FIFOs are essentially directly connected to SW registers, it is an error if
279   // there is ever a need for flow control.
280   assign error_overflow  = tx_valid & ~tx_ready;
281   assign error_underflow = rx_ready & ~rx_valid;
282 
283 
284   // Note on ByteOrder and ByteSwapping.
285   // ByteOrder == 1 is for Little-Endian transmission (i.e. LSB first), which is acheived by default
286   // with the prim_packer_fifo implementation.  Thus we have to swap if Big-Endian transmission
287   // is required (i.e. if ByteOrder == 0).
288   spi_host_data_cdc #(
289     .TxDepth(TxDepth),
290     .RxDepth(RxDepth),
291     .SwapBytes(~ByteOrder)
292   ) u_data_cdc (
293     .clk_i,
294     .rst_ni,
295     .clk_core_i,
296     .rst_core_ni,
297 
298     .tx_data_i         (tx_data),
299     .tx_be_i           (tx_be),
300     .tx_valid_i        (tx_valid),
301     .tx_ready_o        (tx_ready),
302     .tx_watermark_i    (tx_watermark),
303 
304     .core_tx_data_o    (core_tx_data),
305     .core_tx_be_o      (core_tx_be),
306     .core_tx_valid_o   (core_tx_valid),
307     .core_tx_ready_i   (core_tx_ready),
308 
309     .core_rx_data_i    (core_rx_data),
310     .core_rx_valid_i   (core_rx_valid),
311     .core_rx_ready_o   (core_rx_ready),
312 
313     .rx_data_o         (rx_data),
314     .rx_valid_o        (rx_valid),
315     .rx_ready_i        (rx_ready),
316     .rx_watermark_i    (rx_watermark),
317 
318     .tx_empty_o        (tx_empty),
319     .tx_full_o         (tx_full),
320     .tx_qd_o           (tx_qd),
321     .tx_wm_o           (tx_wm),
322     .rx_empty_o        (rx_empty),
323     .rx_full_o         (rx_full),
324     .rx_qd_o           (rx_qd),
325     .rx_wm_o           (rx_wm),
326 
327     .sw_rst_i          (sw_rst),
328     .core_sw_rst_i     (core_sw_rst)
329 );
330 
331   // CDCs for a handful of continuous or pulsed control and status signals
332   logic en_sw;
333   logic enb_error;
334   logic en, core_en;
335 
336   assign en         = en_sw & ~enb_error;
337   assign sw_rst     = reg2hw.control.sw_rst.q;
338   assign en_sw      = reg2hw.control.spien.q;
339 
340   prim_flop_2sync #(
341     .Width(3)
342   ) u_sync_stat_from_core (
343     .clk_i,
344     .rst_ni,
345     .d_i      ({core_rx_stall, core_tx_stall, core_active}),
346     .q_o      ({     rx_stall,      tx_stall,      active})
347   );
348 
349   prim_flop_2sync #(
350     .Width(2)
351   ) u_sync_en_to_core (
352     .clk_i    (clk_core_i),
353     .rst_ni   (rst_core_ni),
354     .d_i      ({en,      sw_rst}),
355     .q_o      ({core_en, core_sw_rst})
356   );
357 
358   spi_host_core #(
359     .NumCS(NumCS)
360   ) u_spi_core (
361     .clk_i           (clk_core_i),
362     .rst_ni          (rst_core_ni),
363 
364     .command_i       (core_command),
365     .command_valid_i (core_command_valid),
366     .command_ready_o (core_command_ready),
367     .en_i            (core_en),
368     .tx_data_i       (core_tx_data),
369     .tx_be_i         (core_tx_be),
370     .tx_valid_i      (core_tx_valid),
371     .tx_ready_o      (core_tx_ready),
372     .rx_data_o       (core_rx_data),
373     .rx_valid_o      (core_rx_valid),
374     .rx_ready_i      (core_rx_ready),
375     .sck_o           (sck),
376     .csb_o           (csb),
377     .sd_o            (sd_out),
378     .sd_en_o         (sd_en),
379     .sd_i,
380     .rx_stall_o      (core_rx_stall),
381     .tx_stall_o      (core_tx_stall),
382     .sw_rst_i        (core_sw_rst),
383     .active_o        (core_active)
384   );
385 
386   logic event_error;
387 
388   logic [4:0] error_vec;
389   logic [4:0] error_mask;
390   logic [4:0] sw_error_status;
391 
392   assign error_vec  = {
393       error_csid_inval,
394       error_cmd_inval,
395       error_underflow,
396       error_overflow,
397       error_busy
398   };
399 
400   assign error_mask = {
401       reg2hw.error_enable.csidinval.q,
402       reg2hw.error_enable.cmdinval.q,
403       reg2hw.error_enable.underflow.q,
404       reg2hw.error_enable.overflow.q,
405       reg2hw.error_enable.cmdbusy.q
406   };
407 
408   assign hw2reg.error_status.csidinval.d = error_csid_inval;
409   assign hw2reg.error_status.cmdinval.d  = error_cmd_inval;
410   assign hw2reg.error_status.underflow.d = error_underflow;
411   assign hw2reg.error_status.overflow.d  = error_overflow;
412   assign hw2reg.error_status.cmdbusy.d   = error_busy;
413 
414   assign hw2reg.error_status.csidinval.de = 1'b1;
415   assign hw2reg.error_status.cmdinval.de  = 1'b1;
416   assign hw2reg.error_status.underflow.de = 1'b1;
417   assign hw2reg.error_status.overflow.de  = 1'b1;
418   assign hw2reg.error_status.cmdbusy.de   = 1'b1;
419 
420   assign sw_error_status[4] = reg2hw.error_status.csidinval.q;
421   assign sw_error_status[3] = reg2hw.error_status.cmdinval.q;
422   assign sw_error_status[2] = reg2hw.error_status.underflow.q;
423   assign sw_error_status[1] = reg2hw.error_status.overflow.q;
424   assign sw_error_status[0] = reg2hw.error_status.cmdbusy.q;
425 
426   assign event_error   = |(error_vec & error_mask);
427   assign enb_error     = |sw_error_status;
428 
429   prim_intr_hw #(.Width(1)) intr_hw_error (
430     .clk_i,
431     .rst_ni,
432     .event_intr_i           (event_error),
433     .reg2hw_intr_enable_q_i (reg2hw.intr_enable.error.q),
434     .reg2hw_intr_test_q_i   (reg2hw.intr_test.error.q),
435     .reg2hw_intr_test_qe_i  (reg2hw.intr_test.error.qe),
436     .reg2hw_intr_state_q_i  (reg2hw.intr_state.error.q),
437     .hw2reg_intr_state_de_o (hw2reg.intr_state.error.de),
438     .hw2reg_intr_state_d_o  (hw2reg.intr_state.error.d),
439     .intr_o                 (intr_error_o)
440   );
441 
442   logic event_spi_event;
443   logic event_idle, event_ready, event_tx_wm, event_rx_wm, event_tx_empty, event_rx_full;
444   logic [5:0] event_vector;
445   logic [5:0] event_mask;
446 
447   assign event_vector= {
448       event_idle, event_ready, event_tx_wm,
449       event_rx_wm, event_tx_empty, event_rx_full
450   };
451 
452   assign event_mask = {
453       reg2hw.event_enable.idle.q,
454       reg2hw.event_enable.ready.q,
455       reg2hw.event_enable.txwm.q,
456       reg2hw.event_enable.rxwm.q,
457       reg2hw.event_enable.txempty.q,
458       reg2hw.event_enable.rxfull.q
459   };
460 
461   assign event_spi_event = |(event_vector & event_mask);
462 
463   logic idle_d, idle_q;
464   logic ready_d, ready_q;
465   logic tx_wm_d, tx_wm_q;
466   logic rx_wm_d, rx_wm_q;
467   logic tx_empty_d, tx_empty_q;
468   logic rx_full_d, rx_full_q;
469 
470   assign event_idle     = idle_d & ~idle_q;
471   assign idle_d         = ~active;
472   assign event_ready    = ready_d & ~ready_q;
473   assign ready_d        = ~command_busy;
474   assign event_tx_wm    = tx_wm_d & ~tx_wm_q;
475   assign tx_wm_d        = tx_wm;
476   assign event_rx_wm    = rx_wm_d & ~rx_wm_q;
477   assign rx_wm_d        = rx_wm;
478   assign event_tx_empty = tx_empty_d & ~tx_empty_q;
479   assign tx_empty_d     = tx_empty;
480   assign event_rx_full  = rx_full_d & ~rx_full_q;
481   assign rx_full_d      = rx_full;
482 
483   always_ff @(posedge clk_i or negedge rst_ni) begin
484     if (!rst_ni) begin
485       idle_q     <= 1'b0;
486       ready_q    <= 1'b0;
487       tx_wm_q    <= 1'b0;
488       rx_wm_q    <= 1'b0;
489       tx_empty_q <= 1'b0;
490       rx_full_q  <= 1'b0;
491     end else begin
492       idle_q     <= idle_d;
493       ready_q    <= ready_d;
494       tx_wm_q    <= tx_wm_d;
495       rx_wm_q    <= rx_wm_d;
496       tx_empty_q <= tx_empty_d;
497       rx_full_q  <= rx_full_d;
498     end
499   end
500 
501   prim_intr_hw #(.Width(1)) intr_hw_spi_event (
502     .clk_i,
503     .rst_ni,
504     .event_intr_i           (event_spi_event),
505     .reg2hw_intr_enable_q_i (reg2hw.intr_enable.spi_event.q),
506     .reg2hw_intr_test_q_i   (reg2hw.intr_test.spi_event.q),
507     .reg2hw_intr_test_qe_i  (reg2hw.intr_test.spi_event.qe),
508     .reg2hw_intr_state_q_i  (reg2hw.intr_state.spi_event.q),
509     .hw2reg_intr_state_de_o (hw2reg.intr_state.spi_event.de),
510     .hw2reg_intr_state_d_o  (hw2reg.intr_state.spi_event.d),
511     .intr_o                 (intr_spi_event_o)
512   );
513 
514 
515   `ASSERT_KNOWN(CioSckKnownO_A, cio_sck_o)
516   `ASSERT_KNOWN(CioSckEnKnownO_A, cio_sck_en_o)
517   `ASSERT_KNOWN(CioCsbKnownO_A, cio_csb_o)
518   `ASSERT_KNOWN(CioCsbEnKnownO_A, cio_csb_en_o)
519   `ASSERT_KNOWN(CioSdKnownO_A, cio_sd_o)
520   `ASSERT_KNOWN(CioSdEnKnownO_A, cio_sd_en_o)
521   `ASSERT_KNOWN(IntrSpiEventKnownO_A, intr_spi_event_o)
522   `ASSERT_KNOWN(IntrErrorKnownO_A, intr_error_o)
523 
524 endmodule : spi_host
</code>
